input.command:
SCR=/tmp/claude-0/-tmp-eff-6jt6zj8r-work/a4eb1cb7-866c-5bbf-8d81-a8d5acd83be3/scratchpad; cat > $SCR/dash.json <<'EOF'
{
  "title": "EFF-1e537256 Web logs overview",
  "description": "Key traffic metrics for the Kibana sample web logs (kibana_sample_data_logs).",
  "options": {"use_margins": true, "sync_cursor": true, "sync_tooltips": false},
  "panels": [
    {"type": "markdown", "id": "b1000000-0000-4000-8000-000000000001",
     "grid": {"x": 0, "y": 0, "w": 48, "h": 3},
     "config": {"content": "## Web logs overview\nRequest volume, response health and payload size for the sample web server logs."}},
    {"type": "vis", "id": "b1000000-0000-4000-8000-000000000002",
     "grid": {"x": 0, "y": 3, "w": 16, "h": 6},
     "config": {
       "type": "metric", "title": "Total requests", "ignore_global_filters": false, "sampling": 1,
       "data_source": {"type": "data_view_spec", "index_pattern": "kibana_sample_data_logs", "time_field": "timestamp"},
       "metrics": [{"type": "primary", "operation": "count", "empty_as_null": false}],
       "styling": {"primary": {"labels": {"alignment": "left"}, "position": "bottom", "value": {"alignment": "right", "sizing": "auto"}}}
     }},
    {"type": "vis", "id": "b1000000-0000-4000-8000-000000000003",
     "grid": {"x": 16, "y": 3, "w": 16, "h": 6},
     "config": {
       "type": "metric", "title": "Average response size (bytes)", "ignore_global_filters": false, "sampling": 1,
       "data_source": {"type": "data_view_spec", "index_pattern": "kibana_sample_data_logs", "time_field": "timestamp"},
       "metrics": [{"type": "primary", "operation": "average", "field": "bytes", "empty_as_null": false}],
       "styling": {"primary": {"labels": {"alignment": "left"}, "position": "bottom", "value": {"alignment": "right", "sizing": "auto"}}}
     }},
    {"type": "vis", "id": "b1000000-0000-4000-8000-000000000004",
     "grid": {"x": 32, "y": 3, "w": 16, "h": 6},
     "config": {
       "type": "metric", "title": "Server error (5xx) requests", "ignore_global_filters": false, "sampling": 1,
       "data_source": {"type": "esql", "query": "FROM kibana_sample_data_logs | WHERE response.keyword RLIKE \"5[0-9][0-9]\" | STATS errors = COUNT(*)"},
       "metrics": [{"type": "primary", "field": "errors", "empty_as_null": false}],
       "styling": {"primary": {"labels": {"alignment": "left"}, "position": "bottom", "value": {"alignment": "right", "sizing": "auto"}}}
     }},
    {"type": "vis", "id": "b1000000-0000-4000-8000-000000000005",
     "grid": {"x": 0, "y": 9, "w": 48, "h": 10},
     "config": {
       "type": "xy", "title": "Requests and 5xx errors over time", "ignore_global_filters": false, "sampling": 1,
       "data_source": {"type": "esql", "query": "FROM kibana_sample_data_logs | EVAL is_5xx = CASE(response.keyword RLIKE \"5[0-9][0-9]\", 1, 0) | STATS requests = COUNT(*), errors_5xx = SUM(is_5xx) BY bucket = BUCKET(@timestamp, 75, ?_tstart, ?_tend)"},
       "layers": [{"type": "line", "ignore_global_filters": false, "sampling": 1,
         "data_source": {"type": "esql", "query": "FROM kibana_sample_data_logs | STATS requests = COUNT(*) BY bucket = BUCKET(@timestamp, 75, ?_tstart, ?_tend)"},
         "x": {"column": "bucket"}, "y": [{"axis_id": "y", "column": "requests"}]}],
       "axis": {"x": {"scale": "ordinal", "title": {"visible": false}}, "y": {"scale": "linear", "title": {"visible": true}}},
       "legend": {"placement": "outside", "position": "right", "visibility": "visible"},
       "styling": {"interpolation": "linear"}
     }}
  ]
}
EOF
curl -sS -m 60 -H "Authorization: ApiKey $KIBANA_TEST_API_KEY" -H "kbn-xsrf: true" -H "Content-Type: application/json" -X POST "$KIBANA_URL/api/dashboards" -d @$SCR/dash.json -w "\nHTTP %{http_code}\n" | cut -c1-1500

